const ts = require('typescript');
const path = require('path');
const fs = require('fs');

const root = process.cwd();
const configPath = path.join(root, 'tsconfig.json');
const configFile = ts.readConfigFile(configPath, ts.sys.readFile);
if (configFile.error) {
  console.error(ts.flattenDiagnosticMessageText(configFile.error.messageText, '\n'));
  process.exit(1);
}
const parsed = ts.parseJsonConfigFileContent(configFile.config, ts.sys, root);
const program = ts.createProgram({
  rootNames: parsed.fileNames,
  options: parsed.options,
});

const changed = [
  'src/components/common-modal/common-modal.tsx',
  'src/components/language-chooser-component/language-chooser-component.tsx',
  'src/hooks/useVersionCheck.ts',
  'src/i18n/locale/en.ts',
  'src/screens/heals-guide-screen/heals-guide-screen.tsx',
  'src/services/firebase/pushnotification.ts',
].map((f) => path.normalize(path.join(root, f)));

const formatDiag = (d) => {
  const file = d.file ? path.relative(root, d.file.fileName) : '<no-file>';
  let loc = '';
  if (d.file && typeof d.start === 'number') {
    const { line, character } = d.file.getLineAndCharacterOfPosition(d.start);
    loc = `:${line + 1}:${character + 1}`;
  }
  return {
    code: d.code,
    category: ts.DiagnosticCategory[d.category],
    file: file + loc,
    message: ts.flattenDiagnosticMessageText(d.messageText, '\n'),
  };
};

const result = [];
for (const abs of changed) {
  const sf = program.getSourceFile(abs);
  if (!sf) {
    result.push({ file: path.relative(root, abs), missingFromProgram: true });
    continue;
  }
  const syntactic = program.getSyntacticDiagnostics(sf);
  const semantic = program.getSemanticDiagnostics(sf);
  const suggestion = program.getSuggestionDiagnostics(sf);
  result.push({
    file: path.relative(root, abs),
    inProgram: true,
    syntactic: syntactic.map(formatDiag),
    semantic: semantic.map(formatDiag),
    suggestion: suggestion.map(formatDiag),
  });
}
console.log(JSON.stringify(result, null, 2));
EOF

